list-files.beforeRequest:
const team = inputs.include_team_drives === 'true';
const form = (value) => encodeURIComponent(value).replace(/[!'()~]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+');
const pageOf = (q, pageToken) => '/files?' + [['q', q], ['fields', 'nextPageToken,files(id,kind,mimeType,name,trashed,parents)'], ['supportsAllDrives', 'true'],
  ['includeItemsFromAllDrives', team ? 'true' : 'false'], ['corpora', team ? 'allDrives' : 'user'], ['pageSize', '1000']]
  .concat(pageToken ? [['pageToken', pageToken]] : []).map(([key, value]) => key + '=' + form(value)).join('&');
const queryOf = (ids) => { const any = ids.map((id) => "'" + id + "' in parents").join(' or '); const scope = ids.length > 1 ? '(' + any + ')' : any; return inputs.includeTrashed === 'true' ? scope : scope + ' and trashed=false'; };
request.url = pageOf(queryOf([inputs.folderId]));
return request;

list-files.afterResponse:
const team = inputs.include_team_drives === 'true';
const form = (value) => encodeURIComponent(value).replace(/[!'()~]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase()).replace(/%20/g, '+');
const pageOf = (q, pageToken) => '/files?' + [['q', q], ['fields', 'nextPageToken,files(id,kind,mimeType,name,trashed,parents)'], ['supportsAllDrives', 'true'],
  ['includeItemsFromAllDrives', team ? 'true' : 'false'], ['corpora', team ? 'allDrives' : 'user'], ['pageSize', '1000']]
  .concat(pageToken ? [['pageToken', pageToken]] : []).map(([key, value]) => key + '=' + form(value)).join('&');
const queryOf = (ids) => { const any = ids.map((id) => "'" + id + "' in parents").join(' or '); const scope = ids.length > 1 ? '(' + any + ')' : any; return inputs.includeTrashed === 'true' ? scope : scope + ' and trashed=false'; };
let first = response;
const files = [];
let level = [inputs.folderId];
for (let depth = 0; depth < (Number(inputs.depthLevel) || 1) && level.length > 0; depth++) {
  const next = [];
  for (let start = 0; start < level.length; start += 50) {
    const q = queryOf(level.slice(start, start + 50));
    let pageToken;
    do {
      const page = first || call({method: 'GET', url: pageOf(q, pageToken)});
      first = null;
      (page.files || []).forEach((file) => { files.push(file); if (file.mimeType === 'application/vnd.google-apps.folder') next.push(file.id); });
      pageToken = page.nextPageToken;
    } while (pageToken);
  }
  level = next;
}
return {type: 'drive#fileList', incompleteSearch: false, files: files};

search-folder.beforeRequest:
const literal = (text) => String(text).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
let q = (inputs.queryTerm || 'name') + ' ' + (inputs.operator || 'contains') + " '" + literal(inputs.query) + "'";
if (inputs.parentFolder) q += " and '" + literal(inputs.parentFolder) + "' in parents";
if (inputs.type === 'file') q += " and mimeType!='application/vnd.google-apps.folder'";
if (inputs.type === 'folder') q += " and mimeType='application/vnd.google-apps.folder'";
const corpora = inputs.include_team_drives === 'true' ? 'allDrives' : 'user';
request.query.q = q;
request.query.corpora = corpora;
return request;

search-folder.afterResponse:
const literal = (text) => String(text).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
let q = (inputs.queryTerm || 'name') + ' ' + (inputs.operator || 'contains') + " '" + literal(inputs.query) + "'";
if (inputs.parentFolder) q += " and '" + literal(inputs.parentFolder) + "' in parents";
if (inputs.type === 'file') q += " and mimeType!='application/vnd.google-apps.folder'";
if (inputs.type === 'folder') q += " and mimeType='application/vnd.google-apps.folder'";
const corpora = inputs.include_team_drives === 'true' ? 'allDrives' : 'user';
const query = {q, fields: 'nextPageToken, files(id, name, mimeType, createdTime, modifiedTime)', supportsAllDrives: 'true', corpora, pageSize: '1000'};
if (inputs.include_team_drives) query.includeItemsFromAllDrives = inputs.include_team_drives;
let files = response.files || [];
let pageToken = response.nextPageToken;
while (pageToken) {
  const page = call({headers: {'x-goog-api-client': 'gdcl/8.0.2 gl-node/26.4.0'}, method: 'GET', url: '/files', query: Object.assign(query, {pageToken})});
  files = files.concat(page.files || []);
  pageToken = page.nextPageToken;
}
return files;

delete_permissions.afterResponse:
const match = (response.permissions || []).find((permission) => permission.emailAddress === inputs.user_email && permission.role === inputs.permission_name);
if (!match) return {removed: false, message: 'Permission not found'};
call({headers: {'x-goog-api-client': 'gdcl/8.0.2 gl-node/26.4.0'}, method: 'DELETE', url: '/files/' + encodeURIComponent(inputs.fileId) + '/permissions/' + encodeURIComponent(match.id || ''), query: {supportsAllDrives: 'true'}});
return {removed: true, message: 'Permission removed'};

