drive_update_file_metadata.beforeRequest:
const starred = String(inputs.starred || '').trim().toLowerCase();
if (starred === 'yes' || starred === 'true') request.body.starred = true;
if (starred === 'no' || starred === 'false') request.body.starred = false;
